create extension if not exists pgcrypto;
create table public.weddings(id uuid primary key default gen_random_uuid(),couple_name text not null,bride_name text,groom_name text,slug text not null unique check(slug~'^[a-z0-9-]+$'),wedding_date date,venue text,description text,hero_image text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.admins(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,wedding_id uuid not null references public.weddings(id) on delete cascade,role text not null check(role in('owner','admin')),created_at timestamptz not null default now(),unique(user_id,wedding_id));
create table public.photo_submissions(id uuid primary key default gen_random_uuid(),wedding_id uuid not null references public.weddings(id) on delete cascade,uploader_name text not null default 'Anonymous Guest',storage_path text not null unique,thumbnail_path text,caption text,media_type text not null,file_size bigint not null check(file_size>0 and file_size<=15728640),created_at timestamptz not null default now());
create table public.message_submissions(id uuid primary key default gen_random_uuid(),wedding_id uuid not null references public.weddings(id) on delete cascade,guest_name text not null default 'Anonymous Guest',message text not null check(char_length(message) between 1 and 1000),visibility text not null default 'public' check(visibility in('public','private')),created_at timestamptz not null default now());
create index photos_recent on public.photo_submissions(wedding_id,created_at desc);create index messages_recent on public.message_submissions(wedding_id,visibility,created_at desc);
create or replace function public.is_wedding_admin(target uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.admins where wedding_id=target and user_id=auth.uid())$$;
alter table public.weddings enable row level security;alter table public.admins enable row level security;alter table public.photo_submissions enable row level security;alter table public.message_submissions enable row level security;
create policy "wedding public read" on public.weddings for select to anon,authenticated using(true);create policy "wedding admin update" on public.weddings for update to authenticated using(public.is_wedding_admin(id)) with check(public.is_wedding_admin(id));
create policy "admins self read" on public.admins for select to authenticated using(user_id=auth.uid());
create policy "photos public read" on public.photo_submissions for select to anon,authenticated using(true);create policy "photos guest insert" on public.photo_submissions for insert to anon,authenticated with check(exists(select 1 from public.weddings where id=wedding_id));create policy "photos admin delete" on public.photo_submissions for delete to authenticated using(public.is_wedding_admin(wedding_id));
create policy "messages visible read" on public.message_submissions for select to anon,authenticated using(visibility='public' or public.is_wedding_admin(wedding_id));create policy "messages guest insert" on public.message_submissions for insert to anon,authenticated with check(exists(select 1 from public.weddings where id=wedding_id));create policy "messages admin delete" on public.message_submissions for delete to authenticated using(public.is_wedding_admin(wedding_id));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('wedding-media','wedding-media',true,15728640,array['image/jpeg','image/png','image/webp','image/heic'])on conflict(id)do nothing;
create policy "wedding images public read" on storage.objects for select to anon,authenticated using(bucket_id='wedding-media');create policy "wedding images guest upload" on storage.objects for insert to anon,authenticated with check(bucket_id='wedding-media' and name~'^[0-9a-f-]+/photos/[A-Za-z0-9-]+\.(jpg|png|webp)$');create policy "wedding images admin delete" on storage.objects for delete to authenticated using(bucket_id='wedding-media' and public.is_wedding_admin(split_part(name,'/',1)::uuid));
alter publication supabase_realtime add table public.photo_submissions;alter publication supabase_realtime add table public.message_submissions;
